import{_ as a,o as t,c as o,a6 as s}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"Shopee SG：封面、规格与变体套图","description":"","frontmatter":{"id":"shopee-localization","title":"Shopee SG：封面、规格与变体套图","chapter":"03","topic":"cross-border","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["ecommerce-skills","visual-copywriting","cross-border-knowledge"],"platform_rule_ids":["shopee"],"order":23.5,"content_kind":"操作教程"},"headers":[],"relativePath":"ecommerce/shopee-localization.md","filePath":"ecommerce/shopee-localization.md"}'),r={name:"ecommerce/shopee-localization.md"};function i(n,e,d,p,l,h){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="shopee-sg封面、规格与变体-逐张制作" tabindex="-1">Shopee SG封面、规格与变体，逐张制作 <a class="header-anchor" href="#shopee-sg封面、规格与变体-逐张制作" aria-label="Permalink to &quot;Shopee SG封面、规格与变体，逐张制作&quot;">​</a></h1><p>本篇以新加坡站DN01收纳盒练习为例，完成封面、场景、结构、尺寸和发货图。SG官方广告学习页提供清晰商品、方形照片和简洁展示建议；这不是所有Shopee市场的统一硬性规格。<a href="https://ads.shopee.sg/learn/faq/520/172" target="_blank" rel="noreferrer">Shopee SG官方指导</a>。</p><h2 id="_1-确定站点、用途和变体" tabindex="-1">1. 确定站点、用途和变体 <a class="header-anchor" href="#_1-确定站点、用途和变体" aria-label="Permalink to &quot;1. 确定站点、用途和变体&quot;">​</a></h2><p>任务表写站点SG、语言英文、商品类目、白色SKU、图片位置。查看当前卖家后台该位置允许的尺寸、格式和数量。练习采用1600×1600方形母版，实际导出按当前要求；其他市场重新核对，不能只换语言。</p><p>准备真实正面、开盖、隔板、配件照片和外尺寸。先做一个SKU，再复制排版给下一个真实颜色。</p><h2 id="_2-封面先让商品清楚" tabindex="-1">2. 封面先让商品清楚 <a class="header-anchor" href="#_2-封面先让商品清楚" aria-label="Permalink to &quot;2. 封面先让商品清楚&quot;">​</a></h2><p>用真实主体放入白色或非常浅的干净背景，保持完整。促销活动信息如果允许使用，也要先核对活动、站点和时间，不能随手写“官方最低价”。本练习封面不放活动字。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>将上传的白色桌面收纳盒照片用于Shopee SG商品封面。保留真实盒体、盖子、颜色、比例和可见标识，商品完整清楚，背景干净浅色，柔和自然阴影。只处理背景和拍摄瑕疵，不重画商品结构。</span></span>
<span class="line"><span>不添加文具、配件、促销文字、优惠券、认证、奖项和水印。不要把一个商品变成两件套，不添加原照片未见的隔板。无法保持外观时仅输出空背景供真实主体合成。</span></span></code></pre></div><p>小尺寸预览时应先看见商品，再看见其他内容。主体太小就删装饰和扩大商品，不靠更艳的底色弥补。</p><h2 id="_3-场景图说明用途" tabindex="-1">3. 场景图说明用途 <a class="header-anchor" href="#_3-场景图说明用途" aria-label="Permalink to &quot;3. 场景图说明用途&quot;">​</a></h2><p>复用<a href="./amazon-listing">Amazon场景副图</a>中真实主体与浅木桌面，换成适用于本店的短句。练习 <code>For everyday desk organization</code>，商品用途清楚即可。道具与发货清单分开，整图生成改变盒子时回空背景合成。</p><h2 id="_4-结构、尺寸与数量单独一张" tabindex="-1">4. 结构、尺寸与数量单独一张 <a class="header-anchor" href="#_4-结构、尺寸与数量单独一张" aria-label="Permalink to &quot;4. 结构、尺寸与数量单独一张&quot;">​</a></h2><p>结构图用开盖和隔板实拍，短句 <code>Removable divider</code>。尺寸图写 <code>External size: 220 × 150 × 120 mm (L × W × H)</code>。发货图写盒体、盖子、隔板数量，不能把场景文具算进去。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>依据商品结构实拍、真实外尺寸和发货清单，整理Shopee SG三张说明图。分别输出结构图、尺寸图、发货图的短标题、准确文字、对应照片和图层顺序。</span></span>
<span class="line"><span>每张只解释一个问题；尺寸保留L/W/H顺序和单位，发货逐项写数量。没有资料支持的防水、耐温、承重、食品接触与认证不写。不要生成数字、产品细节和配件图片，文本后期排版。</span></span></code></pre></div><p>这一步的可见结果是三张信息不同、数字准确、手机能读的说明图，不是三张重复“高品质”的海报。</p><h2 id="_5-复制到第二个颜色sku" tabindex="-1">5. 复制到第二个颜色SKU <a class="header-anchor" href="#_5-复制到第二个颜色sku" aria-label="Permalink to &quot;5. 复制到第二个颜色SKU&quot;">​</a></h2><p>复制源文件，换成灰色真实商品层，保留文字位置、背景和图层结构。逐项核对灰色SKU是否同尺寸、同配件；有差异就更新文字，不能只做调色。导出 <code>DN01_gray_shopee-sg_01-cover_en_v01.jpg</code>，颜色名和实际图片一致。</p><h2 id="_6-上传后看封面和变体" tabindex="-1">6. 上传后看封面和变体 <a class="header-anchor" href="#_6-上传后看封面和变体" aria-label="Permalink to &quot;6. 上传后看封面和变体&quot;">​</a></h2><p>按当前后台界面排序图片，核对变体对应。看搜索结果小图、手机商品页和规格选择，检查文字是否被裁切、活动角标是否遮住商品、同一颜色是否串图。没有进行后台上传时，交付清单标“待上传”，不要把本地打开文件当作平台通过。</p><table tabindex="0"><thead><tr><th>常见返工</th><th>修法</th></tr></thead><tbody><tr><td>促销元素压住主体</td><td>删除非必要装饰，重排封面</td></tr><tr><td>文具像发货配件</td><td>移走道具，改发货图与说明</td></tr><tr><td>灰色SKU用白色图片</td><td>回商品层与变体关联检查</td></tr><tr><td>手机尺寸表太密</td><td>拆成外尺寸与发货两张</td></tr></tbody></table><p>模板入口<a href="./../prompts/P15">P15</a>，其他语言处理看<a href="./localization">本地化</a>。</p>`,21)])])}const m=a(r,[["render",i]]);export{_ as __pageData,m as default};
